q=np.linspace(0,2,300);ax.plot(q,np.maximum(0,1-q),color=ACCENT,lw=2);ax.axvline(1,color=BAD,ls='--',label='Feller threshold');ax.fill_between(q,0,np.maximum(0,1-q),where=q<1,color=WARM,alpha=.2);ax.set_xlabel('Feller ratio $2\kappa\theta/\sigma_C^2$');ax.set_ylabel('Boundary accessibility indicator');ax.set_title('CIR can touch zero when the Feller condition fails',loc='left');ax.legend(fontsize=8)
